const D = { energy: .6, scale: 1, density: .5, grime: .5, speed: 1, hue: 44, x: .5, y: .42, alpha: 1, style: 'concrete', act: 'service', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const deco=(sty==='deco'), dis=(sty==='disused'), diag=(sty==='diagram');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.4,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), gm=cl(P.grime,0,1.4), act=P.act;
const hz=cl(P.y,.26,.74)*Hh, cx=cl(P.x,.05,.95)*W, gH=Math.max(24,Hh-hz);

S.bass=(S.bass||0)*.84+(A.bass||0)*.16;
const T=K.t*spd;
const glow=(.34+.66*en)*(.55+.55*K.intensity)+S.bass*.28;

// ---- the plane, and the drop at the platform edge ------------------------
const yOf=t=>hz+Math.pow(cl(t,0,1),1.7)*gH;
const hwOf=t=>W*(.05+cl(t,0,1)*1.6)*.5*sc;
const dropOf=t=>gH*.13*Math.pow(cl(t,0,1),1.5);      // the trough floor sits lower
const EU=.30;                                        // where the platform edge runs
const uX=(uu,t)=>cx+uu*hwOf(t);

// ---- a train somewhere down the tunnel.
// A WRAPPING monotonic phase: |dPhase| over 8s is a constant, so the light can
// never sit still — and the envelope is smooth and zero at both ends of the
// cycle, so the wrap never becomes a flash. NO strobe, ever.
let rate=.018;
if(act==='rush') rate=.040; else if(act==='nightshift') rate=.008;
const ph=md(T*rate,1);
const bump=Math.pow(Math.sin(Math.PI*ph),1.6);       // smooth: 0 at the seam
const apr=dis?0:bump;                                // a disused platform has no trains
const trT=.03+(1-ph)*.30;                            // it comes up the tunnel toward you
// an independent ambient drift, so something is ALWAYS moving between trains
const amb=.58*Math.sin(T*.077)+.26*Math.sin(T*.139+1.7)+.12*Math.sin(T*.229);

// ---- the platform, baked once ------------------------------------------
const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(P.y*120),Math.round(P.x*120),Math.round(sc*40),Math.round(gm*6),Math.round(dens*6)].join('|');
if(!S.base||S.bk!==bkey||S.base.width!==W||S.base.height!==Hh){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const deckH=diag?md(H+186,360):(deco?md(H+8,360):md(H+178,360));
  const quad=(u0,u1,t0,t1,lower)=>{
    g.beginShape();
    g.vertex(uX(u0,t0),lower?yOf(t0)+dropOf(t0):yOf(t0));
    g.vertex(uX(u1,t0),lower?yOf(t0)+dropOf(t0):yOf(t0));
    g.vertex(uX(u1,t1),lower?yOf(t1)+dropOf(t1):yOf(t1));
    g.vertex(uX(u0,t1),lower?yOf(t1)+dropOf(t1):yOf(t1));
    g.endShape(CLOSE);
  };

  // ---- the track trough first: it lies BEHIND and BELOW the platform ----
  const STR=48;
  for(let i=0;i<STR;i++){
    const t=i/STR, t2=(i+1)/STR;
    g.fill(md(H+178,360),diag?30:10,diag?10:(2+7*Math.pow(t,1.2)),100);
    quad(EU,1.8,t,t2,true);
  }
  // ballast: broken stone between the sleepers
  if(!diag){
    for(let k=0;k<Math.round(340+dens*260);k++){
      const t=.06+Math.pow(fr(k*3.1),.7)*.94;
      const uu=EU+.06+fr(k*3.1+1)*1.6;
      const x=uX(uu,t), y=yOf(t)+dropOf(t);
      const up=fr(k*3.1+2)>.5;
      g.fill(md(H+178,360),8,up?(14+fr(k*3.1+3)*14):4,26+fr(k*3.1+4)*26);
      g.rect(x,y,gH*.004*(.4+t*1.8),gH*.003*(.4+t*1.4));
    }
    // sleepers, running away under the rails
    for(let k=0;k<Math.round(16+dens*14);k++){
      const t=.05+(k/Math.round(16+dens*14))*.95;
      const y=yOf(t)+dropOf(t);
      g.fill(md(H+(dis?-172:174),360),dis?26:12,dis?11:6,72);
      g.rect(uX(EU+.10,t),y,uX(1.5,t)-uX(EU+.10,t),Math.max(.8,gH*.008*t));
    }
  }
  // ---- the platform deck ------------------------------------------------
  for(let i=0;i<STR;i++){
    const t=i/STR, t2=(i+1)/STR;
    let s2,b2;
    if(diag){ s2=24; b2=16+10*t; }
    else if(deco){ s2=14-4*t; b2=14+30*Math.pow(t,1.1); }
    else if(dis){ s2=8-3*t; b2=8+20*Math.pow(t,1.2); }
    else { s2=7-3*t; b2=11+26*Math.pow(t,1.15); }
    g.fill(deckH,cl(s2,0,60),cl(b2,2,88),100);
    quad(-1.8,EU,t,t2,false);
  }
  // the deck's tooth: aggregate, scuff and old gum trodden flat
  if(!diag){
    for(let k=0;k<Math.round((360+dens*260)*(1+gm*.5));k++){
      const t=.05+Math.pow(fr(k*5.3+9),.7)*.95;
      const uu=-1.8+fr(k*5.3+10)*(EU+1.8);
      const x=uX(uu,t), y=yOf(t);
      const up=fr(k*5.3+11)>.5;
      g.fill(deckH,6,up?(46+fr(k*5.3+12)*26):5,14+fr(k*5.3+13)*18);
      g.rect(x,y,gH*.0035*(.4+t*1.7),gH*.0028*(.4+t*1.3));
    }
    for(let k=0;k<Math.round(gm*36);k++){        // gum: the true texture of a platform
      const t=.14+fr(k*7.7)*.84;
      const uu=-1.5+fr(k*7.7+1)*(EU+1.5);
      g.fill(deckH,4,fr(k*7.7+2)>.5?30:8,34);
      g.ellipse(uX(uu,t),yOf(t),gH*.006*t*(.6+fr(k*7.7+3)),gH*.004*t*(.6+fr(k*7.7+3)));
    }
  }
  // deco: patterned tilework laid into the deck
  if(deco){
    for(let r=0;r<26;r++) for(let c=-9;c<4;c++){
      const t0=.04+(r/26)*.96, t1=.04+((r+1)/26)*.96;
      const u0=c*.16, u1=(c+1)*.16;
      if(u0>EU) continue;
      if(((r+c)&1)===0) continue;
      g.fill(md(H+((r+c)%4===1?168:12),360),(r+c)%4===1?38:24,(r+c)%4===1?26:44,46);
      quad(u0,Math.min(u1,EU),t0,t1,false);
    }
  }
  // ---- the tactile paving: the blister studs that warn you off the edge --
  if(!diag){
    const NSx=Math.round(16+dens*10), NSy=Math.round(20+dens*12);
    for(let r=0;r<NSy;r++){
      const t=.04+(r/NSy)*.96;
      for(let c=0;c<NSx;c++){
        const uu=EU-.30+(c/NSx)*.28;
        const x=uX(uu,t), y=yOf(t);
        const rr=Math.max(.8,(uX(uu+.02,t)-uX(uu,t))*.9);
        if(rr<.8) continue;
        g.fill(md(H+2,360),deco?30:52,cl((deco?44:58)*(.4+.8*t),3,88),84);
        g.ellipse(x,y,rr*1.7,rr*.9);
        g.fill(md(H+2,360),deco?24:44,cl((deco?60:80)*(.4+.8*t),3,94),64);
        g.ellipse(x,y-rr*.2,rr*1.3,rr*.5);
      }
    }
  }
  // ---- the edge: the painted line, the coping, and the face that drops ---
  for(let k=0;k<26;k++){
    const t0=.03+(k/26)*.97, t1=.03+((k+1)/26)*.97;
    // the yellow line
    g.fill(diag?md(H+40,360):md(H,360),diag?70:74,cl((diag?70:76)*(.35+.75*t0),3,92),92);
    quad(EU-.055,EU-.012,t0,t1,false);
    // the coping stone at the very lip
    g.fill(deckH,5,cl((dis?18:30)*(.35+.75*t0),2,70),96);
    quad(EU-.012,EU,t0,t1,false);
    // the vertical face of the platform, dropping into the trough
    g.fill(deckH,7,cl(5*(.35+.75*t0),1,30),100);
    g.beginShape();
    g.vertex(uX(EU,t0),yOf(t0)); g.vertex(uX(EU,t1),yOf(t1));
    g.vertex(uX(EU,t1),yOf(t1)+dropOf(t1)); g.vertex(uX(EU,t0),yOf(t0)+dropOf(t0));
    g.endShape(CLOSE);
  }
  S.base=g; S.bk=bkey;
}

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
// BELOW THE HORIZON ONLY — the bg slot underneath must survive untouched
dc.save(); dc.beginPath(); dc.rect(0,hz,W,Hh-hz); dc.clip();
image(S.base,0,0);

// ---- the rails: two lines of steel, and the only truly bright thing here --
// (p5's own quad() is used here; the cached-build block shadows it with its own
//  helper, but that const is scoped to that block and is long out of scope now)
{
  noStroke();
  for(const ru of [EU+.28,EU+.86]){
    for(let k=0;k<26;k++){
      const t0=.03+(k/26)*.97, t1=.03+((k+1)/26)*.97;
      const y0=yOf(t0)+dropOf(t0), y1=yOf(t1)+dropOf(t1);
      const w0=Math.max(.8,gH*.006*t0), w1=Math.max(.8,gH*.006*t1);
      // the railhead takes the approaching headlamp and runs it at you
      const near=cl((t0-trT)/.6,0,1);
      const lit=dis?.10:(.16+apr*(1-near*.5)*1.5);
      fill(dis?md(H-176,360):md(H+180,360), dis?36:6,
           cl((dis?22:34)+62*lit*glow,3,100), cl((58+34*lit)*(.3+.7*t0),0,100)*AL);
      quad(uX(ru,t0)-w0,y0, uX(ru,t0)+w0,y0, uX(ru,t1)+w1,y1, uX(ru,t1)-w1,y1);
    }
  }
}

// ---- the headlamp coming up the tunnel ---------------------------------
if(apr>.004){
  dc.globalCompositeOperation='lighter';
  const hx=uX(EU+.58,trT), hy=yOf(trT)+dropOf(trT)*.4;
  const rr=gH*(.20+.85*(1-ph))*(.5+.8*en)*sc;
  const c=deco?'255,214,150':'255,240,214';
  const rg=dc.createRadialGradient(hx,hy,0,hx,hy,Math.max(5,rr));
  const aa=(0.10+0.34*glow)*apr*AL;             // smooth swell, never a flash
  rg.addColorStop(0,'rgba('+c+','+aa.toFixed(4)+')');
  rg.addColorStop(.35,'rgba('+c+','+(aa*.4).toFixed(4)+')');
  rg.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=rg; dc.fillRect(hx-rr,hy-rr,rr*2,rr*2);
  // and it throws light along the platform deck too
  const px=uX(EU-.5,.55), py=yOf(.55);
  const rr2=gH*.9*sc;
  const rg2=dc.createRadialGradient(hx,hy,0,px,py,Math.max(6,rr2));
  const aa2=(0.05+0.14*glow)*apr*AL;
  rg2.addColorStop(0,'rgba('+c+','+aa2.toFixed(4)+')');
  rg2.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=rg2; dc.fillRect(0,hz,W,gH);
  dc.globalCompositeOperation=oldOp;
}

// ---- the platform's own light, drifting so the station is never frozen ---
{
  dc.globalCompositeOperation='lighter';
  const sx=uX(EU-.6,.6)+amb*W*.16;
  const sy=hz+gH*(.60+.10*Math.sin(T*.053));
  const rr=gH*(.85+.10*Math.sin(T*.037));
  const c=dis?'190,206,230':(diag?'220,230,255':'255,232,180');
  const rg=dc.createRadialGradient(sx,sy,0,sx,sy,Math.max(6,rr));
  const aa=(dis?0.030:0.052)*(0.4+glow)*AL;
  rg.addColorStop(0,'rgba('+c+','+aa.toFixed(4)+')');
  rg.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=rg; dc.fillRect(0,hz,W,gH);
  dc.globalCompositeOperation=oldOp;
}

// ---- draught: the litter a train pushes ahead of itself ------------------
if(!dis&&apr>.02){
  noStroke();
  const NL=Math.round((5+dens*9)*apr);
  for(let i=0;i<NL;i++){
    const t=.20+fr(i*11.3)*.74;
    const uu=-1.2+md(fr(i*11.3+1)+T*.09*(.4+fr(i*11.3+2)),1)*(EU+1.2);
    const x=uX(uu,t), y=yOf(t)-Math.abs(Math.sin(T*1.4+i))*gH*.014*t*apr;
    fill(md(H+4,360),8,cl(60+30*glow,0,96),cl(40*apr,0,54)*AL);
    ellipse(x,y,gH*.006*t*(.5+fr(i*11.3+3)),gH*.004*t*(.5+fr(i*11.3+3)));
  }
}

// ---- haze where the platform runs into the tunnel -----------------------
{
  const hgd=dc.createLinearGradient(0,hz,0,hz+gH*.30);
  const c=dis?'40,46,54':(deco?'52,38,22':(diag?'30,34,58':'44,36,24'));
  hgd.addColorStop(0,'rgba('+c+','+(0.66*AL).toFixed(3)+')');
  hgd.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=hgd; dc.fillRect(0,hz,W,gH*.30);
}

dc.restore();
blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
noStroke(); noTint();
